mapper.select:
SELECT * FROM wiki_sources
WHERE source_type = #{sourceType} AND source_ref = #{sourceRef}
LIMIT 1

mapper.update:
UPDATE wiki_sources
SET title=#{title}, source_type=#{sourceType}, source_ref=#{sourceRef}, file_path=#{filePath}, content_hash=#{contentHash},
    content=#{content}, category=#{category}, software=#{software}, ingested=#{ingested}, ingested_at=#{ingestedAt}
WHERE id=#{id}
